/** Non-rendering references for revision notes, including targets generated by scripts. */
export interface CommentTarget {
  key: string;
  /** A readable description of the original selection, retained after removal. */
  label: string;
  selector: string;
  identity?: { attribute: string; value: string };
  scope?: string;
  scopeUnique?: boolean;
  fingerprint: { tag: string; text: string; textHash: string; attributes: Record<string, string> };
  /** Whether this fingerprint was unique across the page when last attached. */
  unique: boolean;
}

const IDENTITIES = ['id', 'data-id', 'data-key', 'data-node', 'data-name'];
const ATTRIBUTES = ['aria-label', 'role', 'name', 'type', 'href', 'xlink:href', 'src', 'alt', 'title', 'd', 'points', 'x1', 'y1', 'x2', 'y2'];

/** CSS quoted-string escaping works with unusual IDs and does not need CSS.escape in jsdom. */
function quoted(value: string): string {
  return `"${value.replace(/["\\\x00-\x1f\x7f]/g, (c) => `\\${c.charCodeAt(0).toString(16)} `)}"`;
}

function query(doc: Document, selector: string): Element[] {
  try { return Array.from(doc.querySelectorAll(selector)); } catch { return []; }
}

function named(el: Element): { selector: string; identity: { attribute: string; value: string } } | null {
  for (const attribute of IDENTITIES) {
    const value = el.getAttribute(attribute);
    if (!value) continue;
    const selector = `[${attribute}=${quoted(value)}]`;
    if (query(el.ownerDocument, selector).length === 1) return { selector, identity: { attribute, value } };
  }
  return null;
}

function textOf(el: Element): string {
  return (el.textContent ?? '').replace(/\s+/g, ' ').trim();
}

function hash(text: string): string {
  let value = 2166136261;
  for (let i = 0; i < text.length; i++) value = Math.imul(value ^ text.charCodeAt(i), 16777619);
  return (value >>> 0).toString(16);
}

function fingerprint(el: Element): CommentTarget['fingerprint'] {
  const text = textOf(el);
  const attributes: Record<string, string> = {};
  for (const name of ATTRIBUTES) {
    const value = el.getAttribute(name);
    if (value !== null) attributes[name] = value;
  }
  return { tag: el.localName, text: text.slice(0, 240), textHash: hash(text), attributes };
}

function same(el: Element, expected: CommentTarget['fingerprint']): boolean {
  if (el.localName !== expected.tag) return false;
  const actual = fingerprint(el);
  return actual.textHash === expected.textHash && actual.text === expected.text
    && Object.keys(actual.attributes).length === Object.keys(expected.attributes).length
    && Object.entries(expected.attributes).every(([name, value]) => actual.attributes[name] === value);
}

function candidates(root: Document | Element, expected: CommentTarget['fingerprint']): Element[] {
  // getElementsByTagName avoids interpreting imported tag text as a CSS selector.
  return Array.from(root.getElementsByTagName(expected.tag)).filter((el) => same(el, expected));
}

/** No identifier or style is injected into the user's document. */
export function captureCommentTarget(el: Element, key: string, label?: string): CommentTarget {
  const own = named(el);
  const parts: string[] = [];
  let scope: string | undefined;
  for (let current: Element | null = el; current; current = current.parentElement) {
    const anchor = named(current);
    if (anchor) {
      parts.unshift(anchor.selector);
      if (current !== el) scope = anchor.selector;
      break;
    }
    if (['html', 'head', 'body'].includes(current.localName)) {
      parts.unshift(current.localName);
      break;
    }
    const index = current.parentElement ? Array.from(current.parentElement.children).indexOf(current) + 1 : 1;
    parts.unshift(`${current.localName}:nth-child(${index})`);
  }
  const content = Array.from(el.childNodes).map((node) => node.textContent ?? '').join(' ').replace(/\s+/g, ' ').trim();
  const description = el.localName === 'body' ? 'Page background' : `${el.localName}${el.id ? `#${el.id}` : ''}${content ? ` — ${content.slice(0, 100)}` : ''}`;
  const signature = fingerprint(el);
  return {
    key, label: label ?? description, selector: parts.join(' > '),
    ...(own ? { identity: own.identity } : {}),
    ...(scope ? { scope, scopeUnique: candidates(query(el.ownerDocument, scope)[0], signature).length === 1 } : {}),
    fingerprint: signature, unique: candidates(el.ownerDocument, signature).length === 1,
  };
}

/**
 * Existing IDs/data keys are authoritative. Positional paths are context for the
 * LLM, NOT proof of identity. Anonymous targets need an unambiguous fingerprint;
 * a formerly duplicated item is not rebound to its surviving twin by position.
 */
export function matchCommentTarget(doc: Document, target: CommentTarget): Element | null {
  if (target.identity) {
    const { attribute, value } = target.identity;
    const found = query(doc, `[${attribute}=${quoted(value)}]`);
    // A missing/duplicated explicit identity is unavailable, not permission to
    // substitute unrelated lookalike content. The LLM must update the binding.
    return found.length === 1 ? found[0] : null;
  }
  if (['html', 'head', 'body'].includes(target.selector) && target.fingerprint.tag === target.selector) {
    return doc.querySelector(target.selector);
  }
  if (target.scope && target.scopeUnique) {
    const scopes = query(doc, target.scope);
    if (scopes.length === 1) {
      const scoped = candidates(scopes[0], target.fingerprint);
      if (scoped.length === 1) return scoped[0];
      if (scoped.length > 1) return null;
    }
  }
  if (!target.unique) return null;
  const found = candidates(doc, target.fingerprint);
  return found.length === 1 ? found[0] : null;
}

export function validCommentTarget(value: unknown): value is CommentTarget {
  if (!value || typeof value !== 'object') return false;
  const t = value as CommentTarget;
  const f = t.fingerprint;
  return typeof t.key === 'string' && !!t.key && typeof t.label === 'string' && typeof t.selector === 'string'
    && typeof t.unique === 'boolean' && (t.scope === undefined || typeof t.scope === 'string')
    && (t.scopeUnique === undefined || typeof t.scopeUnique === 'boolean')
    && (t.identity === undefined || (!!t.identity && IDENTITIES.includes(t.identity.attribute) && typeof t.identity.value === 'string'))
    && !!f && typeof f.tag === 'string' && f.tag.length > 0 && f.tag.length <= 256
    && typeof f.text === 'string' && typeof f.textHash === 'string'
    && !!f.attributes && typeof f.attributes === 'object' && !Array.isArray(f.attributes)
    && Object.entries(f.attributes).every(([name, entry]) => ATTRIBUTES.includes(name) && typeof entry === 'string');
}
